import hashlib
import json

def cache_key(prompt, model, temperature, system_prompt):
    # include EVERY parameter that affects the output, not just the prompt text
    payload = json.dumps({
        "prompt": prompt, "model": model,
        "temperature": temperature, "system_prompt": system_prompt,
    }, sort_keys=True)
    return hashlib.sha256(payload.encode()).hexdigest()

def get_cached_or_generate(prompt, model, temperature, system_prompt, cache, client):
    key = cache_key(prompt, model, temperature, system_prompt)
    if key in cache:
        return cache[key]
    response = client.chat.completions.create(
        model=model, temperature=temperature,
        messages=[{"role": "system", "content": system_prompt}, {"role": "user", "content": prompt}],
    )
    cache[key] = response.choices[0].message.content
    return cache[key]

